	const firstCover = deck.slides.findIndex((slide) => slide.type === "cover");
	if (firstCover === index) {
		return 0;
	}
	if (firstCover === -1 && index === 0) {
		return 0;
	}
	return 1;
}

export function remapSlideHeadingHtml(
