export function matchStandaloneYoutubeBlock(
	src: string,
): { raw: string; href: string; id: string } | null {
	const candidates: Array<{ raw: string; href: string }> = [];

	const zenn = new RegExp(`^@\\[youtube\\]\\(([^)\\s]+)\\)${BLOCK_END}`).exec(
		src,
	);
	if (zenn?.[1]) {
