	}

	const angled = new RegExp(`^<(https?:\\/\\/[^>\\s]+)>${BLOCK_END}`, "i").exec(
		src,
	);
	if (angled?.[1]) {
		candidates.push({ raw: angled[0], href: angled[1] });
	}

	const mdLink = new RegExp(`^\\[[^\\]]*\\]\\(([^)\\s]+)\\)${BLOCK_END}`).exec(
		src,
	);
	if (mdLink?.[1]) {
