export function cachedBlogEmbedHtml(embed: BlogEmbed): Promise<string> {
	const key = `${embed.kind}:${embed.href}`;
	let pending = cache.get(key);
	if (!pending) {
		pending = blogEmbedHtml(embed, { favicons });
		cache.set(key, pending);
	}
	return pending;
}

