			rehypeShikiFromHighlighter(highlighter, {
				theme: themeName,
				fallbackLanguage: "javascript",
				transformers: [transformerSlideHighlight()],
			}),
		)
		.use(rehypeShikiToClasses)
		.use(rehypeStringify)
