}
export function splitSlides(body: string): string[] {
	const lines = body.replace(/\r\n/g, "\n").split("\n");
	const chunks: string[] = [];
	let buffer: string[] = [];
	let fenceChar: "`" | "~" | null = null;
	let fenceLen = 0;

	const flush = () => {
		const text = buffer.join("\n").trim();
		if (text.length > 0) {
			chunks.push(text);
		}
		buffer = [];
