	for (const line of lines) {
		if (!fenceChar) {
			const open = line.match(/^(`{3,}|~{3,})/);
			if (open) {
				fenceChar = open[1][0] as "`" | "~";
				fenceLen = open[1].length;
				buffer.push(line);
				continue;
			}
			if (/^-{3,}\s*$/.test(line)) {
				flush();
				continue;
			}
			buffer.push(line);
			continue;
		}

		buffer.push(line);
		const close = line.match(/^(`{3,}|~{3,})\s*$/);
		if (close && close[1][0] === fenceChar && close[1].length >= fenceLen) {
