"""旧 Markdown デッキ（HTML コメント記法）を MDX（許可リストのコンポーネント）に変換する。"""
import json
import pathlib
import re
import sys

TYPES = {
    "cover": "Cover",
    "section": "Section",
    "split": "Split",
    "quote": "Quote",
    "code": "Code",
    "figure": "Figure",
    "center": "Center",
    "end": "End",
}
SAFE_PLAIN = re.compile(r"^[^:#{}\[\],&*?|<>=!%@`'\"-][^:#]*$")


def yaml_value(key: str, value: str) -> str:
    if key == "date" and re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        return value
    if key == "unlisted" and value in ("true", "false"):
        return value
    if SAFE_PLAIN.match(value) and ": " not in value and not value.endswith(":"):
        return value
    return json.dumps(value, ensure_ascii=False)


def convert_frontmatter(block: str) -> str:
    lines = []
    for line in block.split("\n"):
        if not line.strip() or line.strip().startswith("#"):
            continue
        key, _, value = line.partition(":")
        value = value.strip()
        if (value.startswith('"') and value.endswith('"')) or (
            value.startswith("'") and value.endswith("'")
        ):
            value = value[1:-1]
        lines.append(f"{key.strip()}: {yaml_value(key.strip(), value)}")
    return "\n".join(lines)


def convert_body(body: str) -> str:
    out: list[str] = []
    lines = body.split("\n")
    fence = None
    i = 0
    clicks_open = False
    while i < len(lines):
        line = lines[i]
        m = re.match(r"^(`{3,}|~{3,})", line)
        if fence:
            out.append(line)
            if re.match(rf"^{re.escape(fence[0])}{{{len(fence)},}}\s*$", line):
                fence = None
            i += 1
            continue
        if m:
            fence = m.group(1)
            out.append(line)
            i += 1
            continue
        t = re.match(r"^\s*<!--\s*type:\s*([a-z]+)\s*-->\s*$", line)
        if t:
            out.append(f"<{TYPES[t.group(1)]} />")
            i += 1
            continue
        if re.match(r"^\s*<!--\s*column\s*-->\s*$", line):
            out.append("<Column />")
            i += 1
            continue
        if re.match(r"^\s*<!--\s*click\s*-->\s*$", line):
            out.append("<Click />")
            i += 1
            continue
        if re.match(r"^\s*<!--\s*clicks\s*-->\s*$", line):
            out.append("<Clicks>")
            clicks_open = True
            i += 1
            continue
        n = re.match(r"^\s*<!--\s*notes\b(.*)$", line)
        if n:
            inner = [n.group(1)] if n.group(1).strip() else []
            i += 1
            while "-->" not in lines[i]:
                inner.append(lines[i])
                i += 1
            tail = lines[i].split("-->")[0]
            if tail.strip():
                inner.append(tail)
            i += 1
            text = "\n".join(inner).strip("\n")
            out.extend(["<Notes>", "", text, "", "</Notes>"])
            continue
        if clicks_open and re.match(r"^-{3,}\s*$", line):
            # リストの後ろ（区切りの手前）で閉じる
            while out and out[-1] == "":
                out.pop()
            out.extend(["", "</Clicks>", ""])
            clicks_open = False
        if "<!--" in line:
            sys.exit(f"未対応のコメント: {line}")
        out.append(line)
        i += 1
    if clicks_open:
        while out and out[-1] == "":
            out.pop()
        out.extend(["", "</Clicks>"])
    return "\n".join(out)


def main() -> None:
    for path in sorted(pathlib.Path("src/slides/decks").glob("*.md")):
        text = path.read_text()
        m = re.match(r"^---\n([\s\S]*?)\n---\n", text)
        assert m, path
        mdx = f"---\n{convert_frontmatter(m.group(1))}\n---\n{convert_body(text[m.end():])}"
        if not mdx.endswith("\n"):
            mdx += "\n"
        path.with_suffix(".mdx").write_text(mdx)
        print(path.with_suffix(".mdx"))


if __name__ == "__main__":
    main()

